import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, step, color, positionLocal, dot, normalize, float, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  const COL = {
    background: '#0b0b10',
    surface: '#14141a',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradA: '#101017',
    gradB: '#1a1a22',
  };

  const group = new Group();
  const timelines = [];
  const disposables = [];
  const primitiveHandles = [];

  // ---- Backdrop stage plane (vertical gradient, ~7x6 at z=-2.5) ----
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const v = uv().y;
    const g = mix(color(COL.gradA), color(COL.gradB), v);
    backdropMat.colorNode = g;
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---- Lights (node-local rim/accent; scene provides ambient+key) ----
  const ambient = new AmbientLight(0xffffff, 0.5);
  group.add(ambient);

  const key = new DirectionalLight(0xffffff, 1.1);
  key.position.set(3, 4, 5);
  group.add(key);

  const rim = new DirectionalLight(new Color(COL.accent), 0.9);
  rim.position.set(-4, 2, 3);
  group.add(rim);

  // ---- Engineered diagonal gradient material builder ----
  function makeSlabMaterial() {
    const mat = new MeshPhysicalNodeMaterial();
    // 135-deg diagonal gradient with hard-stop machined sheen band at 40%
    const p = uv();
    const diag = clamp(p.x.mul(0.5).add(float(1.0).sub(p.y).mul(0.5)), 0.0, 1.0);
    const base = mix(color(COL.gradA), color(COL.gradB), diag);
    // sheen band 0.15 wide at 0.40, +6% value
    const band = smoothstep(0.325, 0.34, diag).mul(smoothstep(0.475, 0.46, diag));
    const sheened = base.add(base.mul(0.06).mul(band));
    mat.colorNode = sheened;
    mat.roughness = 0.5;
    mat.metalness = 0.45;
    mat.clearcoat = 0.2;
    mat.clearcoatRoughness = 0.4;
    return mat;
  }

  // ---- Cell builder ----
  function makeCell(w, h, cx, cy) {
    const cellGroup = new Group();
    const geo = new BoxGeometry(w, h, 0.06);
    const mat = makeSlabMaterial();
    const slab = new Mesh(geo, mat);
    cellGroup.add(slab);
    disposables.push(geo, mat);

    // chamfer-catch accent: thin bright edge frame (top rim slab)
    const chamferGeo = new BoxGeometry(w, 0.02, 0.02);
    const chamferMat = new MeshStandardNodeMaterial();
    chamferMat.colorNode = color(COL.paper);
    chamferMat.roughness = 0.35;
    chamferMat.metalness = 0.5;
    const chamfer = new Mesh(chamferGeo, chamferMat);
    chamfer.position.set(0, h / 2 - 0.01, 0.04);
    cellGroup.add(chamfer);
    disposables.push(chamferGeo, chamferMat);

    // #ff2a38 tick bar 0.4 x 0.05, emissive, top-left inside padding (0.5)
    const tickGeo = new BoxGeometry(0.4, 0.05, 0.02);
    const tickMat = new MeshStandardNodeMaterial();
    tickMat.colorNode = color(COL.accent);
    tickMat.emissiveNode = color(COL.accent).mul(1.3);
    tickMat.roughness = 0.5;
    const tick = new Mesh(tickGeo, tickMat);
    tick.position.set(-w / 2 + 0.5 + 0.2, h / 2 - 0.5, 0.04);
    cellGroup.add(tick);
    disposables.push(tickGeo, tickMat);

    cellGroup.position.set(cx, cy, 0);
    return { cellGroup, slab, tick, w, h };
  }

  // ---- Layout: grid 5.5 x 3.5, gutters 0.25 ----
  // Dominant left cell 3.25 x 3.5, centered left column.
  // Left column center x: grid left edge = -2.75; dominant width 3.25 -> center = -2.75 + 3.25/2 = -1.125
  // Right column secondary cells 2.0 x 1.625 stacked. center x = -2.75 + 3.25 + 0.25 + 1.0 = 1.75
  const dominant = makeCell(3.25, 3.5, -1.125, 0);
  const secTop = makeCell(2.0, 1.625, 1.75, 0.9375);
  const secBottom = makeCell(2.0, 1.625, 1.75, -0.9375);

  group.add(dominant.cellGroup, secTop.cellGroup, secBottom.cellGroup);

  // ---- Text ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjs = [];

  function addText(str, opts, parent, x, y, z) {
    const t = ctx.fontAtlas.createText(str, opts);
    t.position.set(x, y, z);
    parent.add(t);
    textObjs.push(t);
    return t;
  }

  // Header caption above grid, left aligned at x=-2.75, 0.5 above grid (grid top = 1.75)
  addText('ATELIER METRICS / Q2 2026', { fontSize: 24, color: COL.paper, align: 'left', letterSpacingPx: 3 }, group, -2.75, 2.15, 0.1);

  // Dominant cell text
  addText('0.002 mm', { fontSize: 124, color: COL.paper, align: 'left' }, dominant.cellGroup, -3.25 / 2 + 0.5, 0.15, 0.06);
  addText('Case tolerance, CNC pass', { fontSize: 20, color: COL.paper, align: 'left', letterSpacingPx: 2 }, dominant.cellGroup, -3.25 / 2 + 0.5, -0.55, 0.06);

  // Secondary top
  addText('38 h', { fontSize: 68, color: COL.paper, align: 'left' }, secTop.cellGroup, -1.0 + 0.5, 0.2, 0.06);
  addText('Power reserve, NA-01', { fontSize: 18, color: COL.paper, align: 'left', letterSpacingPx: 2 }, secTop.cellGroup, -1.0 + 0.5, -0.35, 0.06);

  // Secondary bottom
  addText('214', { fontSize: 68, color: COL.paper, align: 'left' }, secBottom.cellGroup, -1.0 + 0.5, 0.2, 0.06);
  addText('Components per calibre', { fontSize: 18, color: COL.paper, align: 'left', letterSpacingPx: 2 }, secBottom.cellGroup, -1.0 + 0.5, -0.35, 0.06);

  // ---- Entrance: stagger-cards fade-up, dominant first ----
  const cells = [dominant.cellGroup, secTop.cellGroup, secBottom.cellGroup];
  cells.forEach((c) => { c.position.y -= 0.2; });

  const enterTl = gsap.timeline();
  cells.forEach((c, i) => {
    const finalY = c.position.y + 0.2;
    enterTl.to(c.position, {
      y: finalY,
      duration: 0.5,
      ease: 'power2.out',
    }, i * 0.08);
  });
  timelines.push(enterTl);

  // ---- Hover handlers: press-down + weighted-settle ----
  const cellData = [
    { g: dominant.cellGroup },
    { g: secTop.cellGroup },
    { g: secBottom.cellGroup },
  ];

  group.userData.handlers = {
    onPointerOver: () => {
      cellData.forEach(({ g }) => {
        gsap.to(g.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)', overwrite: true });
      });
    },
    onPointerOut: () => {
      cellData.forEach(({ g }) => {
        gsap.to(g.scale, {
          x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out', overwrite: true,
          onStart: () => { g.scale.set(1.04, 1.04, 1.04); },
        });
      });
    },
    onClick: () => {
      ctx.emit('navigate', { to: 'hub-collection' });
    },
  };

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    gsap.killTweensOf(dominant.cellGroup.scale);
    gsap.killTweensOf(secTop.cellGroup.scale);
    gsap.killTweensOf(secBottom.cellGroup.scale);
    primitiveHandles.forEach((h) => h?.cleanup && h.cleanup());
    disposables.forEach((d) => d?.dispose && d.dispose());
    textObjs.forEach((t) => {
      t.traverse?.((o) => {
        o.geometry?.dispose?.();
        o.material?.dispose?.();
      });
    });
  };

  return group;
}
